// CONFIDENCE: LOW - gating and loops read in full; several field names and two sub-helpers are unresolved. Original 0x1423b8db0.
// Gate: the controller's Role must be ROLE_Authority (byte +0xf0 = AActor::Role), and the world time must have passed the ready-check delay.
UWorld* World = GetWorld();
if (Role == ROLE_Authority && World && ReadyCheckStartTime <= World->TimeSeconds - ReadyCheckDelay)
{
    ReadyCheckPercentage = PercentageToPass;   // proposed name for +0x69c
    // Pass 1: every controller (in the world list) that is an AFortPlayerController and has an Athena PlayerState gets its ready flag cleared.
    for (APlayerController* Peer : World->PlayerControllerList)
    {
        AFortPlayerController* FortPeer = Cast<AFortPlayerController>(Peer);
        if (FortPeer && FortPeer->PlayerState && FortPeer->PlayerState->IsA(AFortPlayerStateAthena::StaticClass()))
        {
            NativeSetPlayerStateReadyToStart(FortPeer->PlayerState, false);   // FUN_14242a0a0, unnamed
        }
    }
    // Pass 2: stamp every Fort controller with the world time and send the prompt.
    for (APlayerController* Peer : World->PlayerControllerList)
    {
        AFortPlayerController* FortPeer = Cast<AFortPlayerController>(Peer);
        if (FortPeer)
        {
            FortPeer->ReadyCheckStampTime = World->TimeSeconds;   // proposed name for the int field at +0x4c8
            FortPeer->ReadyCheckStampFlag = 0;                    // proposed name for +0x4d0
            NativeSendReadyCheckPrompt(FortPeer, QueryText, YesText, NoText);   // FUN_142a3c6a0, unnamed
        }
    }
    return true;
}
return false;
